const CompleteConnectorInfoSchema = z
  .object({
    connectorId: z
      .string()
      .min(1)
      .max(50)
      .exactOptional()
      .openapi({ description: 'Identifier of the connector.' }),
    projectId: z
      .string()
      .min(1)
      .max(50)
      .exactOptional()
      .openapi({
        description:
          'Project ID.\nAny HERE Tracking user must be a member of a Tracking project.\nThe project ID can be implicitly resolved if the user calling the API is a member of a single project.\nIf the user is a member of multiple projects, the `projectId` query parameter needs to be specified explicitly.\n',
      }),
  })
  .openapi({ required: [] })
  .and(
    z
      .object({
        description: z
          .string()
          .max(200)
          .exactOptional()
          .openapi({ description: 'Brief description of the connector.' }),
        driverId: z
          .string()
          .min(1)
          .max(50)
          .openapi({ description: 'Identifier of the driver to be used with this connector.' }),
        enabled: z
          .boolean()
          .openapi({
            description:
              'Enabled state of the connector. If set to false then the connector\nwill not execute periodically.\n',
          }),
        externalCloudInfo: z
          .object({})
          .openapi({
            description:
              "An external cloud-specific object that the driver will use to login to the\nexternal cloud. The structure of this object varies per driver\nimplementation.\nIt is recommended to have dedicated credentials for logging in to\nthe external cloud in order not to violate possible concurrent users\npolicies of the external cloud.\nIn case of the HERE Tracking loopback driver, the maximum\nallowed concurrent user account tokens is 3 per account,\ntherefore it is recommended to create a separate HERE account\nand grant it the required privilege to update the connector's\nproject, and use that account in externalCloudInfo.\n",
          }),
        name: z.string().min(1).max(100).openapi({ description: 'Name of the connector.' }),
        refreshIntervalS: z
          .int()
          .min(60)
          .exactOptional()
          .openapi({
            description:
              "This is the interval (in seconds) to execute the sync process\nbetween the connector's external cloud and HERE Tracking project.\nThe maximum and at the same time default value for callback-type connectors is 900 seconds.\nThe default value for other type of connectors is 3600 seconds and there is no maximum value set.\n",
          }),
      })
      .openapi({
        example: {
          driverId: 'my-driver-1-id',
          enabled: true,
          externalCloudInfo: {
            extAppId: 'ext-app-id',
            extUserId: 'ext-user-id',
            extUserPassword: 'ext-user-password',
          },
          name: 'driver-name',
          refreshIntervalS: 3600,
        },
        required: ['name', 'externalCloudInfo', 'driverId', 'enabled'],
        title: 'connectorInfo',
      }),
  )
  .and(
    z
      .object({
        lastExecTs: z
          .string()
          .max(50)
          .exactOptional()
          .openapi({ description: 'Timestamp of the last connection execution.' }),
      })
      .openapi({ required: [] }),
  )
  .and(
    z
      .object({
        totalAddedDevices: z
          .int()
          .min(0)
          .openapi({ description: 'Number of external devices added to the connector.' }),
      })
      .openapi({ required: ['totalAddedDevices'] }),
  )
  .and(
    z
      .object({
        createdAt: z.iso
          .datetime({ offset: true })
          .openapi({ description: 'Timestamp of the connector creation.' }),
      })
      .openapi({ required: ['createdAt'] }),
  )
  .openapi('CompleteConnectorInfo')

