const ShipmentIdSchema = z
  .string()
  .regex(/^SHP-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/)
  .openapi({ description: 'Shipment ID' })
  .openapi('ShipmentId')

const ShipmentIdsSchema = z
  .array(
    z
      .string()
      .regex(/^SHP-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/)
      .openapi({ description: 'Shipment ID' }),
  )
  .openapi({ description: 'Array of shipment IDs' })
  .openapi('ShipmentIds')

const ShipmentNameSchema = z
  .string()
  .max(50)
  .openapi({ description: 'Name of the shipment' })
  .openapi('ShipmentName')

const ShipmentPlanIdsSchema = z
  .array(
    z
      .string()
      .regex(/^SHPP-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/)
      .openapi({ description: 'Shipment plan ID' }),
  )
  .min(1)
  .max(100)
  .openapi({
    description:
      'Provide array of shipment plan ids to include into the shipment report. If just a single shipment plan id is\ngiven, then the shipment report will include only metrics and shipments for the given shipment plan. If none\nis given, then the shipment report will include all shipment plans.\n',
  })
  .openapi('ShipmentPlanIds')

const ShipmentReportErrorSchema = z
  .object({
    code: z.int().openapi({ description: 'An HTTP status code' }),
    details: z
      .any()
      .exactOptional()
      .openapi({ description: 'An optional object containing more information about the error' }),
    error: z.string().openapi({ description: 'An HTTP error description' }),
    id: z.uuid().openapi({ description: 'An error ID that allows you to trace the error details' }),
    message: z
      .string()
      .exactOptional()
      .openapi({ description: 'Descriptive text that explains the error' }),
  })
  .openapi({ required: ['error', 'code', 'id'] })
  .openapi('ShipmentReportError')

const ShipmentReportIdSchema = z
  .string()
  .regex(/^SHPR-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/)
  .openapi({ description: 'Shipment report ID' })
  .openapi('ShipmentReportId')

const ShipmentReportStatusSchema = z
  .enum(['completed', 'failed', 'ongoing', 'pending'])
  .openapi('ShipmentReportStatus')

const ShipmentRulesBodySchema = z
  .strictObject({
    geofenceIds: z
      .array(z.uuid().openapi({ description: 'Geofence ID' }))
      .max(15)
      .openapi({ description: 'Array of geofence IDs' }),
    ruleIds: z
      .array(z.uuid().openapi({ description: 'Must be a valid UUIDv4.\n' }))
      .max(15)
      .openapi({ description: 'Array of rule IDs' }),
  })
  .openapi({ required: ['ruleIds', 'geofenceIds'] })
  .openapi('ShipmentRulesBody')

const ShipmentScheduleCountSchema = z
  .object({
    SHIPMENT_DELAYED: z
      .number()
      .openapi({ description: 'Number of devices currently in this event state.\n' }),
    SHIPMENT_EARLY: z
      .number()
      .openapi({ description: 'Number of devices currently in this event state.\n' }),
    SHIPMENT_ON_TIME: z
      .number()
      .openapi({ description: 'Number of devices currently in this event state.\n' }),
    eventSource: z.literal('shipmentSchedule'),
  })
  .openapi({ required: ['eventSource', 'SHIPMENT_EARLY', 'SHIPMENT_ON_TIME', 'SHIPMENT_DELAYED'] })
  .and(
    z
      .object({
        ruleId: z.uuid().exactOptional().openapi({ description: 'Must be a valid UUIDv4.\n' }),
        total: z
          .number()
          .openapi({
            description: 'Number of devices associated to the respective rule or rules.',
          }),
      })
      .openapi({ required: ['total'] }),
  )
  .openapi({ title: 'shipmentSchedule' })
  .openapi('ShipmentScheduleCount')

const ShipmentStatusSchema = z
  .enum(['pending', 'ongoing', 'completed', 'cancelled'])
  .openapi({ description: 'Status of the shipment' })
  .openapi('ShipmentStatus')

const StartIndexSchema = z
  .int()
  .min(0)
  .default(0)
  .openapi({ description: 'Start of returned block from a list. Default 0.' })
  .openapi('StartIndex')

const StartedAfterSchema = z.iso
  .datetime({ offset: true })
  .openapi({
    description:
      'Include successfully completed shipments of each shipment plan into the shipment report generation\nwhich started after the provided date.\n',
  })
  .openapi('StartedAfter')

const StartedBeforeSchema = z.iso
  .datetime({ offset: true })
  .openapi({
    description:
      'Include successfully completed shipments of each shipment plan into the shipment report generation\nwhich started before the provided date.\n',
  })
  .openapi('StartedBefore')

const StatusSchema = z.enum(['pending', 'ongoing', 'completed', 'cancelled']).openapi('Status')

