const ValueSchema = z
  .number()
  .openapi({
    description:
      'The value of the report metric, which was specified in the `measure` parameter.\n\n* `measure`: `duration` => `value`: duration of the event in seconds over the time frame\n* `measure`: `occurrence` => `value`: number of event occurrences during the time frame\n* `measure`: `day` => `value`: the number of days the event lasted over the time frame\n* `measure`: `asset` => `value`: the number of assets that generated the event over the time frame\n\nWhen `value` is provided along with `timestamp`, the time frame is the specified interval.\nWhen `value` is provided with `trackingId` or `geofenceId`, the time frame is the whole report period.\n\nAdditionally, if `method` parameter was given, the `value` represents\naverage/cumulative/percentage of the calculated metric.\n',
  })
  .openapi('Value')

