export const postReportsV4Route = createRoute({
  method: 'post',
  path: '/reports/v4',
  tags: ['Reports'],
  summary: 'Starts report creation',
  description:
    'Starts a report creation.\n\nThe request body contains a rule ID, and the report start and end time.\nThe report will be created based on the event data generated by the rule and devices associated to it.\n\nThe supported rule types are:\n* dwelling\n* detention\n* utilization\n\n> Note that both the report start and end timestamps must be earlier than the current time, \n> and no newly ingested data will be automatically added to the report after its creation.\n\nThe created report ID will be provided in the response.\n\nThe generated report is available for one week, after which it will expire \nand will need to be recreated.\nIf there is an already existing report matching the request parameters, its `reportId`\nwill be returned in the response and no new report will be generated.\n',
  request: {
    headers: z.object({
      'X-Request-Id': z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            description:
              'ID used for correlating requests within HERE Tracking. Used for logging and error reporting.\n\nMust be a valid UUIDv4.\n',
            in: 'header',
            name: 'X-Request-Id',
            required: false,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
    query: z.object({
      projectId: z
        .string()
        .min(1)
        .max(50)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'projectId',
            required: false,
            schema: {
              description:
                'Project ID.\nAny HERE Tracking user must be a member of a Tracking project.\nThe project ID can be implicitly resolved if the user calling the API is a member of a single project.\nIf the user is a member of multiple projects, the `projectId` query parameter needs to be specified explicitly.\n',
              maxLength: 50,
              minLength: 1,
              type: 'string',
            },
          },
          description:
            'Project ID.\nAny HERE Tracking user must be a member of a Tracking project.\nThe project ID can be implicitly resolved if the user calling the API is a member of a single project.\nIf the user is a member of multiple projects, the `projectId` query parameter needs to be specified explicitly.\n',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              end: z.iso
                .datetime({ offset: true })
                .openapi({
                  description:
                    'End date of the report period. The end date should be greater than the start date.',
                }),
              ruleId: z.uuid().openapi({ description: 'Rule ID of a dwelling or detention rule.' }),
              start: z.iso
                .datetime({ offset: true })
                .openapi({
                  description:
                    'Start date and time of the report period. When getting reports per interval, this timestamp\ndefines the start of the interval day, week or month.\n\nFor example, to make the report week start on Monday midnight 1st March 2021 in timezone UTC+1:00,\nset the `start` parameter to be `2021-02-28T23:00:00.000Z` (GMT). Now when getting interval reports,\nthe first week would contain data between `2021-02-28T23:00:00.000Z` and `2021-03-07T23:00:00.000Z` (GMT).\n',
                }),
            })
            .openapi({ required: ['ruleId', 'start', 'end'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description:
        'OK\n\nThe report already exists or a new report creation has been started successfully.\nUse the `Gets reports` endpoint to check the report creation status and to query for actual reports.\n',
      content: {
        'application/json': {
          schema: z
            .object({
              reportId: z
                .string()
                .regex(/^REP-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/)
                .min(1)
                .max(50)
                .openapi({ description: 'Report ID' }),
            })
            .openapi({ required: ['reportId'] }),
        },
      },
    },
    202: {
      description:
        'Accepted\n\nThe report creation job has been started successfully. \nUse the `Gets reports` endpoint to check the report creation status and to query for actual reports.\n',
      content: {
        'application/json': {
          schema: z
            .object({
              reportId: z
                .string()
                .regex(/^REP-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/)
                .min(1)
                .max(50)
                .openapi({ description: 'Report ID' }),
            })
            .openapi({ required: ['reportId'] }),
        },
      },
    },
    400: {
      description:
        'Bad request\n\nThe request object is in an incorrect format or has values that are invalid or out of range.\n\nIf available, further error details are provided in the response body.\n',
      content: {
        'application/json': {
          schema: z
            .object({
              code: z.int().openapi({ description: 'An HTTP status code' }),
              details: z
                .any()
                .exactOptional()
                .openapi({
                  description: 'An optional object containing more information about the error',
                }),
              error: z.string().openapi({ description: 'An HTTP error description' }),
              id: z
                .uuid()
                .openapi({ description: 'An error ID that allows you to trace the error details' }),
              message: z
                .string()
                .exactOptional()
                .openapi({ description: 'Descriptive text that explains the error' }),
            })
            .openapi({ required: ['error', 'code', 'id'] }),
          example: {
            code: 400,
            details: { hereErrorCode: 400306 },
            error: 'Bad request',
            id: '5771b3d4-95ae-4959-ac63-fbaa3d5d06ee-lds2',
            message:
              'The request object is in an incorrect format or has values that are invalid or out of range.',
          },
        },
      },
    },
    401: {
      description: 'Unauthorized\n\nThe request did not provide correct authentication details\n',
      content: {
        'application/json': {
          schema: z
            .object({
              code: z.int().openapi({ description: 'An HTTP status code' }),
              details: z
                .any()
                .exactOptional()
                .openapi({
                  description: 'An optional object containing more information about the error',
                }),
              error: z.string().openapi({ description: 'An HTTP error description' }),
              id: z
                .uuid()
                .openapi({ description: 'An error ID that allows you to trace the error details' }),
              message: z
                .string()
                .exactOptional()
                .openapi({ description: 'Descriptive text that explains the error' }),
            })
            .openapi({ required: ['error', 'code', 'id'] }),
          example: {
            code: 401,
            details: { hereErrorCode: 401306 },
            error: 'Unauthorized',
            id: '5771b3d4-95ae-4959-ac63-fbaa3d5d06ee-lds2',
            message: 'The provided credentials are not valid.',
          },
        },
      },
    },
    403: {
      description: 'Forbidden\n\nThe account does not have the correct privileges\n',
      content: {
        'application/json': {
          schema: z
            .object({
              code: z.int().openapi({ description: 'An HTTP status code' }),
              details: z
                .any()
                .exactOptional()
                .openapi({
                  description: 'An optional object containing more information about the error',
                }),
              error: z.string().openapi({ description: 'An HTTP error description' }),
              id: z
                .uuid()
                .openapi({ description: 'An error ID that allows you to trace the error details' }),
              message: z
                .string()
                .exactOptional()
                .openapi({ description: 'Descriptive text that explains the error' }),
            })
            .openapi({ required: ['error', 'code', 'id'] }),
          example: {
            code: 403,
            details: { hereErrorCode: 403306 },
            error: 'Forbidden',
            id: '5771b3d4-95ae-4959-ac63-fbaa3d5d06ee-lds2',
            message: 'The account does not have the correct privileges.',
          },
        },
      },
    },
    404: {
      description: 'Not Found\n\nThe specified resource was not found\n',
      content: {
        'application/json': {
          schema: z
            .object({
              code: z.int().openapi({ description: 'An HTTP status code' }),
              details: z
                .any()
                .exactOptional()
                .openapi({
                  description: 'An optional object containing more information about the error',
                }),
              error: z.string().openapi({ description: 'An HTTP error description' }),
              id: z
                .uuid()
                .openapi({ description: 'An error ID that allows you to trace the error details' }),
              message: z
                .string()
                .exactOptional()
                .openapi({ description: 'Descriptive text that explains the error' }),
            })
            .openapi({ required: ['error', 'code', 'id'] }),
          example: {
            code: 404,
            details: { hereErrorCode: 404306 },
            error: 'Not Found',
            id: '5771b3d4-95ae-4959-ac63-fbaa3d5d06ee-lds2',
            message: 'The specified resource was not found.',
          },
        },
      },
    },
  },
  security: [{ Bearer: [] }],
})

export const getReportsV4HealthRoute = createRoute({
  method: 'get',
  path: '/reports/v4/health',
  tags: ['Reports'],
  summary: 'Gets service health',
  responses: {
    200: {
      description: 'OK\n\nThe service is performing as expected\n',
      content: {
        'application/json': {
          schema: z
            .object({
              message: z.string().exactOptional().openapi({ description: 'Health status' }),
            })
            .openapi({ example: { message: 'healthy' }, required: [] }),
        },
      },
    },
    500: { description: 'Service unavailable\n\nThe service is not performing as expected\n' },
  },
  security: [],
})

